def is_in_L(n):
    # Check if n = 11*k1 + 20*k2 for k1, k2 >= 0
    # We iterate over k2 since 20 is larger
    for k2 in range(n // 20 + 1):
        remainder = n - 20 * k2
        if remainder >= 0 and remainder % 11 == 0:
            return True
    return False

print("Testing small integers:")
for i in range(0, 50):
    result = is_in_L(i)
    print(f"i={i}: In L? {result}")
